module clock_setting (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] orig_time_h,\n    input wire [7:0] orig_time_m,\n    input wire [7:0] target_time_h,\n    input wire [7:0] target_time_m,\n    output reg [7:0] current_time_h,\n    output reg [7:0] current_time_m,\n    output reg valid,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CHANGE_MINUTE_ONES = 3'd1;\n    localparam [2:0] CHANGE_MINUTE_TENS = 3'd2;\n    localparam [2:0] CHANGE_HOUR_ONES = 3'd3;\n    localparam [2:0] CHANGE_HOUR_TENS = 3'd4;\n    localparam [2:0] FINISHED = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [7:0] current_h;\n    reg [7:0] current_m;\n    reg [7:0] target_h;\n    reg [7:0] target_m;\n\n    // Helper function to increment digit with wrap\n    function [3:0] inc_digit;\n        input [3:0] digit;\n        begin\n            inc_digit = (digit == 4'd9) ? 4'd0 : digit + 4'd1;\n        end\n    endfunction\n\n    // Helper function to check time validity\n    function is_valid_time;\n        input [7:0] hours;\n        input [7:0] minutes;\n        begin\n            is_valid_time = (hours[7:4] <= 4'd2) &&\n                           ((hours[7:4] != 4'd2) || (hours[3:0] <= 4'd3)) &&\n                           (minutes[7:4] <= 4'd5) &&\n                           (minutes[3:0] <= 4'd9);\n        end\n    endfunction\n\n    // State register update\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_h <= 8'd0;\n            current_m <= 8'd0;\n            target_h <= 8'd0;\n            target_m <= 8'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            current_time_h <= 8'd0;\n            current_time_m <= 8'd0;\n        end else begin\n            state <= next_state;\n            current_time_h <= current_h;\n            current_time_m <= current_m;\n\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        current_h <= orig_time_h;\n                        current_m <= orig_time_m;\n                        target_h <= target_time_h;\n                        target_m <= target_time_m;\n                        done <= 1'b0;\n                    end\n                end\n\n                CHANGE_MINUTE_ONES: begin\n                    if (current_m[3:0] != target_m[3:0]) begin\n                        current_m[3:0] <= inc_digit(current_m[3:0]);\n                    end\n                end\n\n                CHANGE_MINUTE_TENS: begin\n                    if (current_m[7:4] != target_m[7:4]) begin\n                        current_m[7:4] <= inc_digit(current_m[7:4]);\n                    end\n                end\n\n                CHANGE_HOUR_ONES: begin\n                    if (current_h[3:0] != target_h[3:0]) begin\n                        current_h[3:0] <= inc_digit(current_h[3:0]);\n                    end\n                end\n\n                CHANGE_HOUR_TENS: begin\n                    if (current_h[7:4] != target_h[7:4]) begin\n                        current_h[7:4] <= inc_digit(current_h[7:4]);\n                    end\n                end\n\n                FINISHED: begin\n                    done <= 1'b1;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n\n            // Update valid signal\n            valid <= is_valid_time(current_h, current_m);\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = CHANGE_MINUTE_ONES;\n            end\n\n            CHANGE_MINUTE_ONES: begin\n                if (current_m[3:0] == target_m[3:0]) begin\n                    next_state = CHANGE_MINUTE_TENS;\n                end\n            end\n\n            CHANGE_MINUTE_TENS: begin\n                if (current_m[7:4] == target_m[7:4]) begin\n                    next_state = CHANGE_HOUR_ONES;\n                end\n            end\n\n            CHANGE_HOUR_ONES: begin\n                if (current_h[3:0] == target_h[3:0]) begin\n                    next_state = CHANGE_HOUR_TENS;\n                end\n            end\n\n            CHANGE_HOUR_TENS: begin\n                if (current_h[7:4] == target_h[7:4]) begin\n                    next_state = FINISHED;\n                end\n            end\n\n            FINISHED: begin\n                next_state = IDLE;  // Return to IDLE after finishing\n            end\n\n            default: begin\n                next_state = IDLE;\n            end\n        endcase\n    end\n\nendmodule